def perform_operation(num1, num2, operator):
    """Perform a calculation based on the given operator and numbers."""
    if operator == '+':
        result = num1 + num2
    elif operator == '-':
        result = num1 - num2
    elif operator == '*':
        result = num1 * num2
    elif operator == '/':
        if num2 == 0:
            raise ValueError("Cannot divide by zero.")
        result = num1 / num2
    else:
        raise ValueError(f"Invalid operator '{operator}'. Please use '+' for addition, '-' for subtraction, '*' for multiplication, or '/' for division.")
    return result

# Read two numbers and an operator from the user
